   "id": "za93e9dbe",
   "sez": "mondo",
   "titolo": "Israele: la procuratrice generale autorizza l'indagine su un deputato di estrema destra",
   "orig": "Attorney general approves probe of far-right MK over alleged assault on officer",
   "lead": "La procuratrice generale di Israele ha autorizzato l'apertura di un'indagine giudiziaria nei confronti di un parlamentare del partito di estrema destra Otzma Yehudit, accusato di aver aggredito un agente di polizia. L'episodio contestato si è verificato durante alcuni scontri avvenuti in Cisgiordania circa due settimane fa, quando, nel corso del disordine, un sospetto accusato di aver assalito cittadini palestinesi è riuscito a sfuggire alla custodia delle forze dell'ordine. L'autorizzazione apre un delicato fronte legale all'interno della maggioranza politica. Lo riferisce Haaretz.",
   "more": [
    "Otzma Yehudit è un partito politico israeliano di estrema destra nazionalista, guidato da posizioni radicali sulla presenza israeliana nei territori palestinesi. In Israele, l'avvio di un'indagine penale nei confronti di un membro in carica della Knesset richiede il via libera formale del procuratore generale per via delle prerogative di immunità parlamentare."
   ],
   "fonti": [
    {
     "n": "Haaretz",
     "p": "XX",
     "c": "Tel Aviv",
     "u": "https://www.haaretz.com/israel-news/israel-crime/2026-10-12/ty-article/.premium/israels-ag-allows-probe-into-ben-gvir-party-mk-for-alleged-assault-on-officer/000001a1-2fd6-df2a-a9e7-7fdf892b0000",
     "angolo": "",
     "atlas": "Israel"
    }
   ],
